#### Theme API Service

```typescript
// types/theme.types.ts
export interface TenantTheme {
  id: string;
  tenantId: string;
  themeName: string;
  themeVersion: string;
  themeData: ThemeData;
  assets?: ThemeAssets;
  enabled: boolean;
  darkModeEnabled: boolean;
  darkModeThemeData?: ThemeData;
  accessibilityValidated: boolean;
  validationReport?: ValidationReport;
  createdAt: string;
  updatedAt: string;
  createdBy?: string;
}

export interface ThemeData {
  colors: ColorTokens;
  typography: TypographyTokens;
  spacing: SpacingTokens;
  borderRadius: BorderRadiusTokens;
  shadows: ShadowTokens;
}

export interface ColorTokens {
  primary: string;
  secondary: string;
  success: string;
  warning: string;
  error: string;
  background: string;
  surface: string;
  text: {
    primary: string;
    secondary: string;
    disabled: string;
  };
}

export interface TypographyTokens {
  fontFamily: {
    primary: string;
    monospace: string;
  };
  fontSize: Record<string, string>;
  fontWeight: Record<string, number>;
}

export interface SpacingTokens {
  xs: string;
  sm: string;
  md: string;
  lg: string;
  xl: string;
  '2xl': string;
}

export interface BorderRadiusTokens {
  sm: string;
  md: string;
  lg: string;
  full: string;
}

export interface ShadowTokens {
  sm: string;
  md: string;
  lg: string;
}

export interface ThemeAssets {
  logo?: string;
  logoSmall?: string;
  favicon?: string;
  loginBackground?: string;
}

export interface ValidationReport {
  passed: boolean;
  errors: ValidationError[];
  warnings: ValidationWarning[];
  contrastRatios: ContrastCheckResult[];
}

export interface ValidationError {
  field: string;
  message: string;
  severity: 'error' | 'warning';
}

export interface ValidationWarning {
  field: string;
  message: string;
  recommendation: string;
}

export interface ContrastCheckResult {
  foreground: string;
  background: string;
  ratio: number;
  wcagAA: boolean;
  wcagAAA: boolean;
}

// services/theme.service.ts
export async function fetchTenantTheme(tenantId: string): Promise<TenantTheme | null> {
  const response = await fetch(`/api/tenants/${tenantId}/theme`, {
    headers: {
      'Authorization': `Bearer ${getAuthToken()}`,
      'Content-Type': 'application/json'
    }
  });

  if (!response.ok) {
    if (response.status === 404) return null;
    throw new Error(`Failed to fetch tenant theme: ${response.statusText}`);
  }

  return response.json();
}

export async function validateTenantTheme(themeData: ThemeData): Promise<ValidationReport> {
  const response = await fetch('/api/themes/validate', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${getAuthToken()}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ themeData })
  });

  if (!response.ok) {
    throw new Error(`Theme validation failed: ${response.statusText}`);
  }

  return response.json();
}

export async function updateTenantTheme(
  tenantId: string,
  themeData: Partial<TenantTheme>
): Promise<TenantTheme> {
  const response = await fetch(`/api/tenants/${tenantId}/theme`, {
    method: 'PUT',
    headers: {
      'Authorization': `Bearer ${getAuthToken()}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(themeData)
  });

  if (!response.ok) {
    throw new Error(`Failed to update tenant theme: ${response.statusText}`);
  }

  return response.json();
}
```

