#### Styled-Components Theme Provider

```typescript
// contexts/TenantThemeProvider.tsx
import React, { createContext, useContext, useEffect, useState, useMemo } from 'react';
import { ThemeProvider as StyledThemeProvider } from 'styled-components';
import { TenantTheme, ThemeData } from '../types/theme.types';
import { fetchTenantTheme } from '../services/theme.service';
import { useTenantContext } from './TenantContext';
import { defaultTheme } from '../themes/default.theme';
import { mergeThemes } from '../utils/theme.utils';

interface TenantThemeContextValue {
  theme: ThemeData;
  tenantTheme: TenantTheme | null;
  loading: boolean;
  error: Error | null;
  refreshTheme: () => Promise<void>;
  isDarkMode: boolean;
  toggleDarkMode: () => void;
}

const TenantThemeContext = createContext<TenantThemeContextValue | undefined>(undefined);

export const TenantThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { tenantId } = useTenantContext();
  const [tenantTheme, setTenantTheme] = useState<TenantTheme | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Load tenant theme
  const loadTheme = async () => {
    if (!tenantId) {
      setTenantTheme(null);
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      const theme = await fetchTenantTheme(tenantId);
      setTenantTheme(theme);
      setError(null);
    } catch (err) {
      console.error('Failed to load tenant theme:', err);
      setError(err as Error);
      setTenantTheme(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTheme();
  }, [tenantId]);

  // Merge default theme with tenant overrides
  const mergedTheme = useMemo(() => {
    if (!tenantTheme || !tenantTheme.enabled) {
      return defaultTheme;
    }

    const baseTheme = isDarkMode && tenantTheme.darkModeEnabled && tenantTheme.darkModeThemeData
      ? tenantTheme.darkModeThemeData
      : tenantTheme.themeData;

    return mergeThemes(defaultTheme, baseTheme);
  }, [tenantTheme, isDarkMode]);

  const toggleDarkMode = () => {
    setIsDarkMode(prev => !prev);
  };

  const contextValue: TenantThemeContextValue = {
    theme: mergedTheme,
    tenantTheme,
    loading,
    error,
    refreshTheme: loadTheme,
    isDarkMode,
    toggleDarkMode
  };

  return (
    <TenantThemeContext.Provider value={contextValue}>
      <StyledThemeProvider theme={mergedTheme}>
        {children}
      </StyledThemeProvider>
    </TenantThemeContext.Provider>
  );
};

export const useTenantTheme = (): TenantThemeContextValue => {
  const context = useContext(TenantThemeContext);
  if (!context) {
    throw new Error('useTenantTheme must be used within TenantThemeProvider');
  }
  return context;
};

// utils/theme.utils.ts
export function mergeThemes(baseTheme: ThemeData, overrideTheme: Partial<ThemeData>): ThemeData {
  return {
    colors: {
      ...baseTheme.colors,
      ...overrideTheme.colors,
      text: {
        ...baseTheme.colors.text,
        ...(overrideTheme.colors?.text || {})
      }
    },
    typography: {
      ...baseTheme.typography,
      ...overrideTheme.typography,
      fontFamily: {
        ...baseTheme.typography.fontFamily,
        ...(overrideTheme.typography?.fontFamily || {})
      },
      fontSize: {
        ...baseTheme.typography.fontSize,
        ...(overrideTheme.typography?.fontSize || {})
      },
      fontWeight: {
        ...baseTheme.typography.fontWeight,
        ...(overrideTheme.typography?.fontWeight || {})
      }
    },
    spacing: {
      ...baseTheme.spacing,
      ...overrideTheme.spacing
    },
    borderRadius: {
      ...baseTheme.borderRadius,
      ...overrideTheme.borderRadius
    },
    shadows: {
      ...baseTheme.shadows,
      ...overrideTheme.shadows
    }
  };
}
```

