#### Phase 4: Asset Management with CDN

```typescript
// hooks/useTenantAssets.ts
import { useState, useEffect } from 'react';
import { useTenantContext } from '../contexts/TenantContext';

export interface TenantAssets {
  logo: string;
  logoSmall: string;
  favicon: string;
  loginBackground?: string;
}

const DEFAULT_ASSETS: TenantAssets = {
  logo: '/assets/default-logo.svg',
  logoSmall: '/assets/default-logo-sm.svg',
  favicon: '/favicon.ico'
};

export function useTenantAssets(): TenantAssets {
  const { tenantId } = useTenantContext();
  const [assets, setAssets] = useState<TenantAssets>(DEFAULT_ASSETS);

  useEffect(() => {
    if (!tenantId) {
      setAssets(DEFAULT_ASSETS);
      return;
    }

    // Fetch tenant-specific assets from CDN
    fetch(`/api/tenants/${tenantId}/assets`)
      .then(response => response.json())
      .then(data => {
        setAssets({
          logo: data.logo || DEFAULT_ASSETS.logo,
          logoSmall: data.logoSmall || DEFAULT_ASSETS.logoSmall,
          favicon: data.favicon || DEFAULT_ASSETS.favicon,
          loginBackground: data.loginBackground
        });
      })
      .catch(err => {
        console.error('Failed to load tenant assets:', err);
        setAssets(DEFAULT_ASSETS);
      });
  }, [tenantId]);

  return assets;
}

// components/TenantLogo.tsx
import React from 'react';
import { useTenantAssets } from '../hooks/useTenantAssets';

interface TenantLogoProps {
  size?: 'small' | 'large';
  alt?: string;
}

export const TenantLogo: React.FC<TenantLogoProps> = ({ size = 'large', alt = 'Logo' }) => {
  const assets = useTenantAssets();
  const logoSrc = size === 'small' ? assets.logoSmall : assets.logo;

  return (
    <img
      src={logoSrc}
      alt={alt}
      style={{
        maxWidth: size === 'small' ? '120px' : '240px',
        height: 'auto'
      }}
      onError={(e) => {
        // Fallback to default logo on error
        e.currentTarget.src = size === 'small'
          ? '/assets/default-logo-sm.svg'
          : '/assets/default-logo.svg';
      }}
    />
  );
};
```

