#### Phase 5: Theme Accessibility Validation

```typescript
// services/theme-validation.service.ts
import { ThemeData, ValidationReport, ContrastCheckResult } from '../types/theme.types';

/**
 * Calculate WCAG contrast ratio between two colors
 */
function calculateContrastRatio(foreground: string, background: string): number {
  const getLuminance = (color: string): number => {
    // Convert hex to RGB
    const hex = color.replace('#', '');
    const r = parseInt(hex.substr(0, 2), 16) / 255;
    const g = parseInt(hex.substr(2, 2), 16) / 255;
    const b = parseInt(hex.substr(4, 2), 16) / 255;

    // Apply gamma correction
    const rsRGB = r <= 0.03928 ? r / 12.92 : Math.pow((r + 0.055) / 1.055, 2.4);
    const gsRGB = g <= 0.03928 ? g / 12.92 : Math.pow((g + 0.055) / 1.055, 2.4);
    const bsRGB = b <= 0.03928 ? b / 12.92 : Math.pow((b + 0.055) / 1.055, 2.4);

    return 0.2126 * rsRGB + 0.7152 * gsRGB + 0.0722 * bsRGB;
  };

  const l1 = getLuminance(foreground);
  const l2 = getLuminance(background);

  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);

  return (lighter + 0.05) / (darker + 0.05);
}

/**
 * Validate theme accessibility
 */
export function validateThemeAccessibility(themeData: ThemeData): ValidationReport {
  const errors: ValidationReport['errors'] = [];
  const warnings: ValidationReport['warnings'] = [];
  const contrastRatios: ContrastCheckResult[] = [];

  // Check primary text on background
  const primaryTextRatio = calculateContrastRatio(
    themeData.colors.text.primary,
    themeData.colors.background
  );
  contrastRatios.push({
    foreground: themeData.colors.text.primary,
    background: themeData.colors.background,
    ratio: primaryTextRatio,
    wcagAA: primaryTextRatio >= 4.5,
    wcagAAA: primaryTextRatio >= 7
  });

  if (primaryTextRatio < 4.5) {
    errors.push({
      field: 'colors.text.primary',
      message: `Primary text contrast ratio (${primaryTextRatio.toFixed(2)}:1) fails WCAG AA (requires 4.5:1)`,
      severity: 'error'
    });
  }

  // Check secondary text on background
  const secondaryTextRatio = calculateContrastRatio(
    themeData.colors.text.secondary,
    themeData.colors.background
  );
  contrastRatios.push({
    foreground: themeData.colors.text.secondary,
    background: themeData.colors.background,
    ratio: secondaryTextRatio,
    wcagAA: secondaryTextRatio >= 4.5,
    wcagAAA: secondaryTextRatio >= 7
  });

  if (secondaryTextRatio < 4.5) {
    warnings.push({
      field: 'colors.text.secondary',
      message: `Secondary text contrast ratio (${secondaryTextRatio.toFixed(2)}:1) fails WCAG AA`,
      recommendation: 'Use a darker shade for better readability'
    });
  }

  // Check primary button contrast
  const primaryButtonRatio = calculateContrastRatio(
    '#FFFFFF', // Assuming white text on primary button
    themeData.colors.primary
  );
  contrastRatios.push({
    foreground: '#FFFFFF',
    background: themeData.colors.primary,
    ratio: primaryButtonRatio,
    wcagAA: primaryButtonRatio >= 4.5,
    wcagAAA: primaryButtonRatio >= 7
  });

  if (primaryButtonRatio < 4.5) {
    errors.push({
      field: 'colors.primary',
      message: `Primary button contrast ratio (${primaryButtonRatio.toFixed(2)}:1) fails WCAG AA`,
      severity: 'error'
    });
  }

  // Validate color values are valid hex
  const colorFields = [
    'primary', 'secondary', 'success', 'warning', 'error', 'background', 'surface'
  ];
  for (const field of colorFields) {
    const color = themeData.colors[field as keyof typeof themeData.colors];
    if (typeof color === 'string' && !/^#[0-9A-Fa-f]{6}$/.test(color)) {
      errors.push({
        field: `colors.${field}`,
        message: `Invalid hex color format: ${color}`,
        severity: 'error'
      });
    }
  }

  // Validate font sizes are valid CSS values
  for (const [key, value] of Object.entries(themeData.typography.fontSize)) {
    if (!/^\d+(\.\d+)?(rem|px|em)$/.test(value)) {
      errors.push({
        field: `typography.fontSize.${key}`,
        message: `Invalid font size value: ${value}`,
        severity: 'error'
      });
    }
  }

  const passed = errors.length === 0;

  return {
    passed,
    errors,
    warnings,
    contrastRatios
  };
}
```

